package hk.overlander.journal;
import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.os.*;
import android.view.KeyEvent;
import android.widget.Toast;
import java.io.File;

public class MusicPlaybackService extends Service {
  private MediaPlayer player;private MediaSession session;private AudioManager audio;private boolean ready=false;private String current;
  private final AudioManager.OnAudioFocusChangeListener focus=change->{if(change<=0)pause();};
  @Override public void onCreate(){super.onCreate();audio=(AudioManager)getSystemService(AUDIO_SERVICE);if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("music","窗邊收音機",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"Overlander");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onStop(){stopSelf();}public boolean onMediaButtonEvent(Intent i){KeyEvent e=i.getParcelableExtra(Intent.EXTRA_KEY_EVENT);if(e!=null&&e.getAction()==KeyEvent.ACTION_DOWN){if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PAUSE)pause();else if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_STOP)stopSelf();else if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PLAY)play();else if(ready&&player.isPlaying())pause();else play();return true;}return super.onMediaButtonEvent(i);}});registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));}
  private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
  @Override public int onStartCommand(Intent i,int flags,int id){startForeground(2002,notification());if(i==null){stopSelf();return START_NOT_STICKY;}String a=i.getAction();if("stop".equals(a)){stopSelf();return START_NOT_STICKY;}if("pause".equals(a)){pause();return START_NOT_STICKY;}String path=i.getStringExtra("path");if(path==null)path=getSharedPreferences("journey",0).getString("musicPath",null);if(path!=null&&!path.equals(current)){load(path);}else if("toggle".equals(a)&&ready&&player.isPlaying())pause();else if(ready)play();else if(path!=null)load(path);else fail("請先選擇音樂");return START_NOT_STICKY;}
  private void load(String path){try{File f=new File(path);String root=getFilesDir().getCanonicalPath()+File.separator;if(!f.getCanonicalPath().startsWith(root)||!f.isFile())throw new Exception();if(player!=null)player.release();ready=false;current=path;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(path);player.setLooping(true);player.setOnPreparedListener(p->{ready=true;play();});player.setOnErrorListener((p,w,e)->{fail("音樂無法播放，請重新選擇");return true;});player.prepareAsync();session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,path.endsWith("rail.wav")?"原創合成火車聲":"窗邊音樂").putString(MediaMetadata.METADATA_KEY_ARTIST,"THE OVERLANDER").build());update();}catch(Exception e){fail("音樂檔案無法開啟");}}
  private void play(){if(!ready||player==null)return;if(audio.requestAudioFocus(focus,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){fail("未能取得音訊播放權");return;}try{startForeground(2002,notification());session.setActive(true);player.start();update();}catch(Exception e){fail("播放失敗");}}
  private void pause(){if(ready&&player!=null&&player.isPlaying())player.pause();audio.abandonAudioFocus(focus);update();stopForeground(false);}
  private PendingIntent action(String a,int request){return PendingIntent.getService(this,request,new Intent(this,MusicPlaybackService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
  private Notification notification(){boolean playing=ready&&player!=null&&player.isPlaying();Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"music"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("漫遊日誌 · 窗邊收音機").setContentText(playing?"背景播放中":"暫停 / 準備播放").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setVisibility(Notification.VISIBILITY_PUBLIC).setOnlyAlertOnce(true).setOngoing(playing).addAction(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"暫停":"播放",action(playing?"pause":"play",1)).addAction(android.R.drawable.ic_menu_close_clear_cancel,"停止",action("stop",2)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).build();}
  private void update(){boolean playing=ready&&player!=null&&player.isPlaying();session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,ready?player.getCurrentPosition():0,playing?1:0).build());((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2002,notification());}
  private void fail(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();stopSelf();}
  @Override public void onDestroy(){unregisterReceiver(noisy);if(player!=null)player.release();audio.abandonAudioFocus(focus);session.setActive(false);session.release();stopForeground(true);super.onDestroy();}
  @Override public IBinder onBind(Intent i){return null;}
}
